def inference_checks(base,loader,model,norm,case,prediction): # Verify the actual original V1 forward path in this independent inference process.
    poisoned=copy.deepcopy(case);poisoned.pop('reference',None);poisoned['states'][1:]=7654321.;poisoned_prediction=base.rollout(model,poisoned,norm);scale=np.asarray(norm['state_scale'])[None,None,:];poison_error=float(np.max(np.abs(prediction-poisoned_prediction)/scale));assert poison_error==0. # No future native field or saved reference may influence a cold historical-model rollout.
    permutation=np.random.default_rng(20261025).permutation(case['nodes']);inverse=np.argsort(permutation);changed=copy.deepcopy(poisoned) # Keep every original node, integration point and interface entity under a one-to-one renumbering.
    for key in ['xyz','features','state_mask']: changed[key]=changed[key][permutation] # Reindex all spatial input features and physical field support together.
    for key in ['states','prescribed','prescribed_mask']: changed[key]=changed[key][:,permutation] # Preserve the entire temporal history and all known boundary data.
    changed['edges']=inverse[changed['edges']];permuted=base.rollout(model,changed,norm)[:,inverse];permutation_error=float(np.max(np.abs(prediction-permuted)/scale));assert permutation_error<1.e-3 # V1 has no V2 steel/MPC hard-head indices; its graph and known-boundary maps alone follow the permutation.
    return {'future_reference_removed':True,'all_future_states_poisoned':True,'maximum_normalized_future_poison_difference':poison_error,'maximum_normalized_full_entity_permutation_difference':permutation_error,'permutation_tolerance':1.e-3,'all_native_entities':case['nodes'],'all_original_frames':case['times'],'prediction_source':'Original V1 AbsoluteStateOperator through complex_operator.rollout; no V2 physical head'} # Invariance is separate from field accuracy or supported physical validity.
