            prior=historical[row['id']];assert row['native_reference']['sha256']==prior['native_reference']['sha256'];old=prior['accuracy']['mean_physical_group_relative_L2'];new=row['accuracy']['mean_physical_group_relative_L2'];pairs.append({'id':row['id'],'split':row['split'],'v2_strategy':strategy,'same_native_sha256':row['native_reference']['sha256'],'V1_active_mean_group_error':old,'V2_mean_group_error':new,'absolute_error_reduction_V1_minus_V2':old-new,'relative_error_reduction':(old-new)/old if old else None,'V1_negative':prior['neural_negative'],'V2_negative':row['neural_negative'],'V1_physics_status':prior['physics']['status'],'V2_physics_status':row['physics']['status']}) # Positive reduction has an explicit direction and never hides worse physical residuals.
